#define DDRC_POISONCFG_RD_POISON_INTR_EN(x)      (((uint32_t)(((uint32_t)(x)) << DDRC_POISONCFG_RD_POISON_INTR_EN_SHIFT)) & DDRC_POISONCFG_RD_POISON_INTR_EN_MASK)

#define DDRC_POISONCFG_RD_POISON_INTR_CLR_MASK   (0x1000000U)
