#define DDRC_PCCFG_GO2CRITICAL_EN(x)             (((uint32_t)(((uint32_t)(x)) << DDRC_PCCFG_GO2CRITICAL_EN_SHIFT)) & DDRC_PCCFG_GO2CRITICAL_EN_MASK)

#define DDRC_PCCFG_PAGEMATCH_LIMIT_MASK          (0x10U)
