#define DDRC_PCFGQOS1_0_RQOS_MAP_TIMEOUTB(x)     (((uint32_t)(((uint32_t)(x)) << DDRC_PCFGQOS1_0_RQOS_MAP_TIMEOUTB_SHIFT)) & DDRC_PCFGQOS1_0_RQOS_MAP_TIMEOUTB_MASK)

#define DDRC_PCFGQOS1_0_RQOS_MAP_TIMEOUTR_MASK   (0x7FF0000U)
