#define HDCP_A_HDCPCFG1_SPARE(x)                 (((uint8_t)(((uint8_t)(x)) << HDCP_A_HDCPCFG1_SPARE_SHIFT)) & HDCP_A_HDCPCFG1_SPARE_MASK)
/*! @} */

